<?php
declare(strict_types=1);
if(PHP_SAPI!=='cli'){http_response_code(404);exit(1);}
require_once __DIR__.'/../config/discovery.php';
$passed=0;
function discovery_assert(bool $condition):void{if(!$condition)throw new RuntimeException('Discovery assertion failed.');}
function discovery_expect(callable $operation,string $type=Throwable::class):void{try{$operation();}catch(Throwable $error){if($error instanceof $type)return;throw new RuntimeException('Unexpected discovery error.');}throw new RuntimeException('Expected discovery rejection.');}
function discovery_test(string $name,callable $operation):void{global$passed;try{$operation();++$passed;fwrite(STDOUT,'PASS '.$name.PHP_EOL);}catch(Throwable){fwrite(STDERR,'FAIL '.$name.PHP_EOL);exit(1);}}
function discovery_sample_wanted(array $replace=[]):array{return array_replace(['user_id'=>1,'title'=>'Suche ein Sofa','keywords'=>'sofa','description'=>'Ein normales Sofa für das Wohnzimmer.','manufacturer'=>'','model'=>'','category_id'=>null,'min_cents'=>null,'max_cents'=>null,'condition_label'=>'any','country_code'=>'DE','scope'=>'country','zip'=>'','latitude'=>null,'longitude'=>null,'radius_km'=>null],$replace);}
function discovery_sample_listing(array $replace=[]):array{return array_replace(['id'=>1,'seller_id'=>2,'status'=>'active','title'=>'Bequemes Sofa','description'=>'Normales gepflegtes Möbelstück für das Wohnzimmer.','category_id'=>1,'price_cents'=>12999,'current_bid_cents'=>null,'condition_label'=>'used','country_code'=>'DE','zip'=>'10115','latitude'=>null,'longitude'=>null,'type'=>'fixed','ends_at'=>null],$replace);}

discovery_test('unicode_normalization_and_stopwords',static function():void{discovery_assert(discovery_normalize(' ÄÖÜ ß Éléphant Łódź ') === 'aeoeue ss elephant lodz');discovery_assert(discovery_tokens('Ich suche eine Couch und einen Rucksack')===['sofa','rucksack']);});
discovery_test('local_synonym_matching',static function():void{discovery_assert(discovery_score(discovery_sample_wanted(['keywords'=>'couch']),discovery_sample_listing())['score']>0);discovery_assert(discovery_score(discovery_sample_wanted(['keywords'=>'notebook']),discovery_sample_listing(['title'=>'Gepflegter Laptop']))['score']>0);});
discovery_test('bounded_typo_tolerance_and_unrelated_rejection',static function():void{discovery_assert(discovery_score(discovery_sample_wanted(['keywords'=>'fernglas']),discovery_sample_listing(['title'=>'Fernglaas mit Tasche']))['score']>0);discovery_assert(discovery_score(discovery_sample_wanted(['keywords'=>'kamera']),discovery_sample_listing())['score']===0);});
discovery_test('most_requested_terms_must_match',static function():void{$wanted=discovery_sample_wanted(['keywords'=>'sofa grau holz']);discovery_assert(discovery_score($wanted,discovery_sample_listing(['title'=>'Graues Sofa']))['score']===0);discovery_assert(discovery_score($wanted,discovery_sample_listing(['title'=>'Sofa grau']))['score']>0);});
discovery_test('country_boundary_and_explicit_international',static function():void{$listing=discovery_sample_listing(['country_code'=>'NL']);discovery_assert(discovery_score(discovery_sample_wanted(),$listing)['score']===0);discovery_assert(discovery_score(discovery_sample_wanted(['scope'=>'international']),$listing)['score']>0);});
discovery_test('integer_price_limits_are_inclusive',static function():void{$wanted=discovery_sample_wanted(['min_cents'=>12999,'max_cents'=>12999]);discovery_assert(discovery_score($wanted,discovery_sample_listing())['score']>0);discovery_assert(discovery_score($wanted,discovery_sample_listing(['current_bid_cents'=>13000]))['score']===0);});
discovery_test('category_and_condition_are_hard_filters',static function():void{discovery_assert(discovery_score(discovery_sample_wanted(['category_id'=>2]),discovery_sample_listing())['score']===0);discovery_assert(discovery_score(discovery_sample_wanted(['condition_label'=>'new']),discovery_sample_listing())['score']===0);});
discovery_test('manufacturer_and_model_do_not_fuzzily_change_identity',static function():void{$wanted=discovery_sample_wanted(['keywords'=>'kamera','manufacturer'=>'Example','model'=>'X100']);$listing=discovery_sample_listing(['title'=>'Example X100 Kamera']);discovery_assert(discovery_score($wanted,$listing)['score']>0);$listing['title']='Example X200 Kamera';discovery_assert(discovery_score($wanted,$listing)['score']===0);});
discovery_test('radius_is_great_circle_and_unknown_coordinates_fail_closed',static function():void{$wanted=discovery_sample_wanted(['latitude'=>52.52,'longitude'=>13.405,'radius_km'=>40]);$listing=discovery_sample_listing(['latitude'=>52.4,'longitude'=>13.07]);$distance=discovery_distance_km(52.52,13.405,52.4,13.07);discovery_assert($distance>20&&$distance<35);discovery_assert(discovery_score($wanted,$listing)['score']>0);$wanted['radius_km']=10;discovery_assert(discovery_score($wanted,$listing)['score']===0);$wanted['radius_km']=40;$listing['latitude']=null;discovery_assert(discovery_score($wanted,$listing)['score']===0);});
discovery_test('zero_coordinates_are_valid_not_missing',static function():void{discovery_assert(discovery_distance_km(0,0,0,0)===0.0);$wanted=discovery_sample_wanted(['latitude'=>0,'longitude'=>0,'radius_km'=>1]);discovery_assert(discovery_score($wanted,discovery_sample_listing(['latitude'=>0,'longitude'=>0]))['score']>0);discovery_expect(static fn()=>discovery_distance_km(91,0,0,0),InvalidArgumentException::class);});
discovery_test('exact_postcode_remains_country_bound',static function():void{$wanted=discovery_sample_wanted(['zip'=>'10115','scope'=>'international']);discovery_assert(discovery_score($wanted,discovery_sample_listing())['score']>0);discovery_assert(discovery_score($wanted,discovery_sample_listing(['country_code'=>'FR']))['score']===0);});
discovery_test('neighbour_postcode_format_variants_match',static function():void{$wanted=discovery_sample_wanted(['country_code'=>'PL','zip'=>'00-001']);discovery_assert(discovery_score($wanted,discovery_sample_listing(['country_code'=>'PL','zip'=>'00001']))['score']>0);});
discovery_test('expired_inactive_and_self_offers_do_not_match',static function():void{discovery_assert(discovery_score(discovery_sample_wanted(),discovery_sample_listing(['status'=>'ended']))['score']===0);discovery_assert(discovery_score(discovery_sample_wanted(),discovery_sample_listing(['seller_id'=>1]))['score']===0);discovery_assert(discovery_score(discovery_sample_wanted(),discovery_sample_listing(['type'=>'auction','ends_at'=>'2000-01-01 00:00:00']))['score']===0);});
discovery_test('text_frequency_and_table_names_reject_injection',static function():void{discovery_expect(static fn()=>discovery_text(['q'=>[]],'q'),InvalidArgumentException::class);discovery_expect(static fn()=>discovery_text(['q'=>"\xff"],'q'),InvalidArgumentException::class);discovery_expect(static fn()=>discovery_frequency(['notify_mode'=>'all']),InvalidArgumentException::class);discovery_expect(static fn()=>discovery_table('wanted; DROP TABLE users'),InvalidArgumentException::class);});

if(in_array('--database',$argv,true)){
    if(getenv('DB_DATABASE')!=='gunindex_rebuild_test'){fwrite(STDERR,"Discovery DB checks require the isolated synthetic database.\n");exit(2);}
    require_once __DIR__.'/../config/bootstrap.php';
    $suffix=bin2hex(random_bytes(8));$ids=[];
    foreach(['owner','seller','other'] as $role){$name='discovery_'.$role.'_'.$suffix;$q=$pdo->prepare("INSERT INTO users(username,email,password_hash,full_name,zip,city) VALUES (?,?,?,'Synthetic discovery fixture','10115','Teststadt')");$q->execute([$name,$name.'@example.invalid',auth_hash('Synthetic '.bin2hex(random_bytes(20)))]);$ids[$role]=(int)$pdo->lastInsertId();}
    $category=(int)catalog_categories($pdo,true)[0]['id'];$stem='Discovery'.$suffix;
    $newListing=static function(string $detail='')use($pdo,$ids,$category,$stem):int{
        $id=market_save_listing($pdo,$ids['seller'],['title'=>$stem.' Sofa '.$detail,'description'=>'Synthetic ordinary household furniture for isolated discovery regression tests.','category_id'=>(string)$category,'type'=>'fixed','status'=>'active','price'=>'129.99','buyout_price'=>'','duration_days'=>'1','zip'=>'10115','city'=>'Teststadt','country_code'=>'DE','condition_label'=>'used','pickup'=>'1','shipping'=>'1','accept_rules'=>'1']);
        discovery_enqueue_listing($pdo,$id);return$id;
    };
    $base=['title'=>$stem.' Sofa gesucht','description'=>'Synthetic request for ordinary furniture used only in regression tests.','keywords'=>'sofa','category_id'=>(string)$category,'manufacturer'=>'','model'=>'','min_price'=>'100.00','max_price'=>'150.00','condition_label'=>'used','country_code'=>'DE','scope'=>'country','zip'=>'','radius_km'=>'','notify_mode'=>'instant'];
    $finishBackfill=static function(string $kind,int $id)use($pdo):void{for($page=0;$page<100;$page++){discovery_scan_query($pdo,$kind,$id,100);$q=$pdo->prepare('SELECT backfill_complete FROM '.discovery_table($kind).' WHERE id=?');$q->execute([$id]);if((int)$q->fetchColumn()===1)return;}throw new RuntimeException('Synthetic backfill budget exceeded.');};
    $countNotifications=static function(string $key)use($pdo,$ids):int{$q=$pdo->prepare('SELECT COUNT(*) FROM market_notifications WHERE user_id=? AND event_key=?');$q->execute([$ids['owner'],$key]);return(int)$q->fetchColumn();};
    $existing=$newListing('existing');$wanted=discovery_save_wanted($pdo,$ids['owner'],$base);$finishBackfill('wanted',$wanted);
    discovery_test('database_backfill_returns_existing_matches_without_alert',static function()use($pdo,$wanted,$existing,$ids,$countNotifications):void{$matches=discovery_matches($pdo,'wanted',$wanted,$ids['owner']);discovery_assert(in_array($existing,array_map(static fn($row)=>(int)$row['id'],$matches),true));discovery_assert($countNotifications('discovery:wanted:'.$wanted.':'.$existing)===0);});
    $fresh=$newListing('new');
    discovery_test('database_new_event_notifies_once_despite_duplicate_events',static function()use($pdo,$wanted,$fresh,$countNotifications):void{discovery_scan_query($pdo,'wanted',$wanted,100);discovery_scan_query($pdo,'wanted',$wanted,100);discovery_assert($countNotifications('discovery:wanted:'.$wanted.':'.$fresh)===1);$q=$pdo->prepare("SELECT COUNT(*) FROM market_discovery_matches WHERE query_kind='wanted' AND query_id=? AND listing_id=?");$q->execute([$wanted,$fresh]);discovery_assert((int)$q->fetchColumn()===1);});
    discovery_test('database_owner_isolation_and_invalid_ranges',static function()use($pdo,$wanted,$ids,$base):void{discovery_expect(static fn()=>discovery_owner_query($pdo,'wanted',$wanted,$ids['other']),DomainException::class);discovery_expect(static fn()=>discovery_transition($pdo,'wanted',$wanted,$ids['other'],'pause'),DomainException::class);discovery_expect(static fn()=>discovery_save_wanted($pdo,$ids['owner'],array_replace($base,['min_price'=>'200.00','max_price'=>'100.00'])),InvalidArgumentException::class);discovery_expect(static fn()=>discovery_save_wanted($pdo,$ids['owner'],array_replace($base,['title'=>'Schusswaffen gesucht'])),InvalidArgumentException::class);});
    discovery_test('database_pause_then_resume_backfills_without_old_alarm',static function()use($pdo,$wanted,$ids,$newListing,$finishBackfill,$countNotifications):void{discovery_transition($pdo,'wanted',$wanted,$ids['owner'],'pause');$during=$newListing('while paused');discovery_assert(discovery_scan_query($pdo,'wanted',$wanted,100)['processed']===0);discovery_transition($pdo,'wanted',$wanted,$ids['owner'],'resume');$finishBackfill('wanted',$wanted);discovery_assert($countNotifications('discovery:wanted:'.$wanted.':'.$during)===0);});
    $off=discovery_save_wanted($pdo,$ids['owner'],array_replace($base,['notify_mode'=>'off']));$finishBackfill('wanted',$off);$offListing=$newListing('off');
    discovery_test('database_off_matches_without_notifications',static function()use($pdo,$off,$offListing,$countNotifications):void{discovery_scan_query($pdo,'wanted',$off,100);$q=$pdo->prepare("SELECT notification_state FROM market_discovery_matches WHERE query_kind='wanted' AND query_id=? AND listing_id=?");$q->execute([$off,$offListing]);discovery_assert($q->fetchColumn()==='off');discovery_assert($countNotifications('discovery:wanted:'.$off.':'.$offListing)===0);});
    $searchInput=['name'=>'Synthetic saved search '.$suffix,'q'=>$stem,'category_id'=>(string)$category,'type'=>'fixed','min_price'=>'100.00','max_price'=>'150.00','country_code'=>'DE','scope'=>'country','origin_country'=>'DE','zip'=>'','radius_km'=>'','sort'=>'newest','notify_mode'=>'instant'];
    $search=discovery_save_search($pdo,$ids['owner'],$searchInput);$finishBackfill('search',$search);$savedFresh=$newListing('saved search');
    discovery_test('database_saved_filters_are_reused_and_duplicates_rejected',static function()use($pdo,$search,$savedFresh,$ids,$searchInput,$countNotifications):void{discovery_scan_query($pdo,'search',$search,100);discovery_assert($countNotifications('discovery:search:'.$search.':'.$savedFresh)===1);discovery_expect(static fn()=>discovery_save_search($pdo,$ids['owner'],$searchInput),InvalidArgumentException::class);discovery_expect(static fn()=>discovery_matches($pdo,'search',$search,$ids['other']),DomainException::class);});
    $daily=discovery_save_wanted($pdo,$ids['owner'],array_replace($base,['notify_mode'=>'daily']));$finishBackfill('wanted',$daily);$dailyOther=discovery_save_wanted($pdo,$ids['owner'],array_replace($base,['title'=>$stem.' weiteres Sofa gesucht','notify_mode'=>'daily']));$finishBackfill('wanted',$dailyOther);$dailyFresh=$newListing('daily');discovery_scan_query($pdo,'wanted',$daily,100);discovery_scan_query($pdo,'wanted',$dailyOther,100);
    discovery_test('database_daily_digest_is_once_per_day_not_instant',static function()use($pdo,$daily,$dailyOther,$dailyFresh,$ids,$countNotifications):void{discovery_assert($countNotifications('discovery:wanted:'.$daily.':'.$dailyFresh)===0);$pdo->prepare("UPDATE market_discovery_matches SET matched_at=UTC_TIMESTAMP()-INTERVAL 2 DAY WHERE query_kind='wanted' AND query_id IN (?,?) AND listing_id=?")->execute([$daily,$dailyOther,$dailyFresh]);$old=getenv('DISCOVERY_DIGEST_HOUR_UTC');putenv('DISCOVERY_DIGEST_HOUR_UTC=0');try{discovery_daily_digests($pdo,100);discovery_daily_digests($pdo,100);}finally{if($old===false)putenv('DISCOVERY_DIGEST_HOUR_UTC');else putenv('DISCOVERY_DIGEST_HOUR_UTC='.$old);}discovery_assert($countNotifications('discovery:digest:'.gmdate('Y-m-d'))===1);$body=$pdo->prepare('SELECT body FROM market_notifications WHERE user_id=? AND event_key=?');$body->execute([$ids['owner'],'discovery:digest:'.gmdate('Y-m-d')]);discovery_assert(str_starts_with((string)$body->fetchColumn(),'1 neue passende Angebote'));$q=$pdo->prepare('SELECT COUNT(*) FROM market_discovery_digests WHERE user_id=? AND digest_date=UTC_DATE()');$q->execute([$ids['owner']]);discovery_assert((int)$q->fetchColumn()===1);});
    discovery_test('database_archived_queries_are_not_silently_restored',static function()use($pdo,$wanted,$ids,$base):void{discovery_transition($pdo,'wanted',$wanted,$ids['owner'],'archive');discovery_expect(static fn()=>discovery_transition($pdo,'wanted',$wanted,$ids['owner'],'resume'),DomainException::class);discovery_expect(static fn()=>discovery_save_wanted($pdo,$ids['owner'],$base,$wanted),DomainException::class);});
}
fwrite(STDOUT,'Discovery checks passed: '.$passed.PHP_EOL);
